[package]
name = "scene_regen"
version = "0.1.0"
edition = "2021"

[dependencies]
bevy_ecs = { path = "/data/repo/crates/bevy_ecs" }
bevy_app = { path = "/data/repo/crates/bevy_app" }
bevy_reflect = { path = "/data/repo/crates/bevy_reflect" }
bevy_scene = { path = "/data/repo/crates/bevy_scene" }
bevy_core = { path = "/data/repo/crates/bevy_core" }
bevy_transform = { path = "/data/repo/crates/bevy_transform" }
bevy_math = { path = "/data/repo/crates/bevy_math" }
bevy_time = { path = "/data/repo/crates/bevy_time" }
serde = "1.0"

use std::collections::HashMap;

use bevy_app::AppTypeRegistry;
use bevy_core::Name;
use bevy_ecs::{
    prelude::{Component, Resource},
    reflect::ReflectResource,
    schedule::Schedule,
    system::FromWorld,
    world::World,
};
use bevy_math::{Mat3A, Vec3A};
use bevy_reflect::{Reflect, ReflectSerialize};
use bevy_scene::DynamicScene;
use bevy_transform::components::{GlobalTransform, Transform};
use bevy_utils::Duration;

#[derive(Component, Reflect, Default)]
#[reflect(Component)]
struct ComponentA {
    pub x: f32,
    pub y: f32,
}

#[derive(Component, Reflect)]
#[reflect(Component)]
struct ComponentB {
    pub value: String,
    #[reflect(skip_serializing)]
    pub _time_since_startup: Duration,
}

impl FromWorld for ComponentB {
    fn from_world(world: &mut World) -> Self {
        let time = world.resource::<bevy_time::Time>();
        ComponentB {
            _time_since_startup: time.elapsed(),
            value: "Default Value".to_string(),
        }
    }
}

#[derive(Resource, Reflect, Default)]
#[reflect(Resource)]
struct ResourceA {
    pub score: u32,
}

fn main() {
    let mut app = bevy_app::App::new();

    app.init_resource::<AppTypeRegistry>();
    app.register_type::<ComponentA>();
    app.register_type::<ComponentB>();
    app.register_type::<ResourceA>();
    app.register_type::<Name>();
    app.register_type::<Transform>();
    app.register_type::<GlobalTransform>();
    app.register_type::<bevy_math::Vec3>();
    app.register_type::<bevy_math::Vec3A>();
    app.register_type::<bevy_math::Quat>();
    app.register_type::<bevy_math::Mat3A>();
    app.register_type::<bevy_math::Mat4>();
    app.register_type::<bevy_math::Affine3A>();
    app.register_type::<String>();
    app.register_type::<u32>();
    app.register_type::<f32>();
    app.register_type::<u64>();
    app.register_type::<Duration>();
    app.register_type::<bevy_utils::Duration>();

    let mut world = World::new();
    world.insert_resource(app.world().resource::<AppTypeRegistry>().clone());
    world.insert_resource(app.world().resource::<AppTypeRegistry>().clone());
    let _ = Schedule::default();

    let mut scene_world = World::new();

    let type_registry = world.resource::<AppTypeRegistry>().clone();
    scene_world.insert_resource(type_registry);

    let mut component_b = ComponentB::from_world(&mut world);
    component_b.value = "hello".to_string();
    scene_world.spawn((
        component_b,
        ComponentA { x: 1.0, y: 2.0 },
        Transform::IDENTITY,
        Name::new("joe"),
    ));
    scene_world.spawn(ComponentA { x: 3.0, y: 4.0 });
    scene_world.insert_resource(ResourceA { score: 1 });

    let scene = DynamicScene::from_world(&scene_world);

    let type_registry = world.resource::<AppTypeRegistry>();
