use bevy_core::Name;
use bevy_ecs::{
    component::Component,
    prelude::Resource,
    reflect::{AppTypeRegistry, ReflectComponent, ReflectResource},
    world::{FromWorld, World},
};
use bevy_reflect::Reflect;
use bevy_scene::DynamicScene;
use bevy_time::Time;
use bevy_transform::components::{GlobalTransform, Transform};
use bevy_utils::Duration;
use std::fs;

#[derive(Component, Reflect, Default)]
#[reflect(Component)]
struct ComponentA {
    pub x: f32,
    pub y: f32,
}

#[derive(Component, Reflect)]
#[reflect(Component)]
struct ComponentB {
    pub value: String,
    #[reflect(skip_serializing)]
    pub _time_since_startup: Duration,
}

impl FromWorld for ComponentB {
    fn from_world(world: &mut World) -> Self {
        let time = world.resource::<Time>();
        ComponentB {
            _time_since_startup: time.elapsed(),
            value: "Default Value".to_string(),
        }
    }
}

#[derive(Resource, Reflect, Default)]
#[reflect(Resource)]
struct ResourceA {
    pub score: u32,
}

fn setup_registry(world: &mut World) {
    world.init_resource::<AppTypeRegistry>();
    world.insert_resource(Time::default());
    {
        let type_registry = world.resource::<AppTypeRegistry>().clone();
        let mut registry = type_registry.write();
        registry.register::<ComponentA>();
        registry.register::<ComponentB>();
        registry.register::<ResourceA>();
        registry.register::<Name>();
        registry.register::<Transform>();
        registry.register::<GlobalTransform>();
        registry.register::<bevy_math::Vec3>();
        registry.register::<bevy_math::Vec3A>();
        registry.register::<bevy_math::Quat>();
        registry.register::<bevy_math::Mat3A>();
        registry.register::<bevy_math::Mat4>();
        registry.register::<bevy_math::Affine3A>();
        registry.register::<String>();
        registry.register::<u32>();
        registry.register::<u64>();
        registry.register::<f32>();
        registry.register::<Duration>();
    }
}

fn main() {
    // --- Test 1: load the committed scene file ---
    let mut world = World::new();
    setup_registry(&mut world);
    let in_byte = fs::read("/data/repo/assets/scenes/load_scene_example.scn.ron").unwrap();
    let mut deserializer = bevy_scene::ron::de::Deserializer::from_bytes(&in_byte).unwrap();
    let scene_deserializer = bevy_scene::serde::SceneDeserializer {
        type_registry: &world.resource::<AppTypeRegistry>().read(),
    };
    let result = scene_deserializer.deserialize(&mut deserializer);
    match result {
        Ok(scene) => {
            println!("LOAD: OK, {} entities, {} resources", scene.entities.len(), scene.resources.len());
            let mut map = bevy_ecs::entity::EntityHashMap::default();
            let mut dst = World::new();
            setup_registry(&mut dst);
            match scene.write_to_world(&mut dst, &mut map) {
                Ok(()) => println!("WRITE: OK"),
                Err(e) => println!("WRITE: ERR {}", e),
            }
        }
        Err(e) => println!("LOAD: ERR {}", deserializer.span_error(e)),
    }
}

